import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Filter out near-duplicates (correlated pairs with |r| >= 0.6)
    correlated_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:, i], feats.x[:, j])[0,1]) >= 0.6:
                correlated_pairs.add((min(fid1, fid2), max(fid1, fid2)))

    # Build clusters of correlated features
    clusters = []
    used = set()
    for fid1, fid2 in correlated_pairs:
        if fid1 in used or fid2 in used:
            continue
        cluster = {fid1, fid2}
        used.update(cluster)
        # Expand cluster by adding more correlated features
        for fid in feats.ids:
            if fid in used or fid in cluster:
                continue
            if any((min(fid, f), max(fid, f)) in correlated_pairs for f in cluster):
                cluster.add(fid)
                used.add(fid)
        clusters.append(cluster)

    # Find strong individual features (t-test p < 0.05)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
        if p_val < 0.05:
            strong_features.append((fid, abs(t_stat)))

    # Sort by effect size
    strong_features.sort(key=lambda x: x[1], reverse=True)

    # Select top drivers (avoiding near-duplicates)
    drivers = []
    seen = set()
    for fid, _ in strong_features:
        if len(drivers) >= MAX_DRIVERS:
            break
        # Check if this feature belongs to a cluster with already selected drivers
        in_cluster = False
        for cluster in clusters:
            if fid in cluster:
                if any(f in drivers for f in cluster):
                    in_cluster = True
                    break
        if not in_cluster and fid not in seen:
            drivers.append(fid)
            seen.add(fid)

    # Build columns list avoiding near-duplicates
    columns = []
    for fid, _ in strong_features:
        if len(columns) >= 20:  # Limit to prevent overfitting
            break
        in_cluster = any(fid in c for c in clusters)
        if not in_cluster and fid not in columns:
            columns.append(fid)

    # Add interaction terms between top features
    products = []
    for i, fid1 in enumerate(columns[:5]):  # Top 5 features
        for j, fid2 in enumerate(columns[i+1:], i+1):
            if len(products) >= 10:  # Limit interactions
                break
            products.append((fid1, fid2))

    # Build loadings for weighted score (using top features)
    loadings = {}
    for i, (fid, _) in enumerate(strong_features[:5]):
        loadings[fid] = 1.0 / (i + 1)  # Inverse rank weighting

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

